def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([1, 1]), fmt([3, 1, 1]), fmt([1, 1, 1, 1]), fmt([2, 2, 2, 4]), fmt([1, 2, 3, 4]),
             fmt([1, 1, 2, 4, 8]), fmt([10 ** 9] * 4), fmt([4, 2, 1, 1]), fmt([2, 1, 1, 2, 2])]
    for n in (3, 5, 8, 12, 20, 30):
        for hi in (2, 3):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    n = 100000
    tests.append(fmt([1] * n))
    tests.append(fmt([10 ** 9] * n))
    tests.append(fmt([rng.randint(1, 2) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 3) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10 ** 9) for _ in range(n)]))
    # powers of two in decreasing order then ones: long cascades
    seq = []
    while len(seq) < n:
        seq += [2 ** k for k in range(16, -1, -1)] + [1] * rng.randint(1, 5)
    tests.append(fmt(seq[:n]))
    return tests

